using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckSports;
using LWS.TruckSports.Editor;
namespace LWS.TruckCurling.Editor {
public static class CurlingAuthoring {
 public const string Folder="TruckCurling",Scene="Assets/TruckCurling/Scenes/TruckCurling.unity";
 static Mesh StoneMesh(){string path="Assets/TruckCurling/Materials/Circular stone collision.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh!=null)return mesh;var cylinder=GameObject.CreatePrimitive(PrimitiveType.Cylinder);mesh=UnityEngine.Object.Instantiate(cylinder.GetComponent<MeshFilter>().sharedMesh);var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]=Vector3.Scale(vertices[i],new Vector3(CurlingRules.Radius*2,.3f,CurlingRules.Radius*2));mesh.vertices=vertices;mesh.name="Identical circular truck-stone footprint";mesh.RecalculateBounds();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,path);UnityEngine.Object.DestroyImmediate(cylinder);return mesh;}
 static void Ring(string name,Vector3 center,float radius,Material mat,float width=.07f){var line=new GameObject(name).AddComponent<LineRenderer>();line.useWorldSpace=true;line.sharedMaterial=mat;line.positionCount=97;line.startWidth=line.endWidth=width;for(int i=0;i<97;i++){float a=i*Mathf.PI*2/96;line.SetPosition(i,center+new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius));}}
 public static void Create(){var m=SportsEventAuthoring.Begin<CurlingMatch>(Folder);m.teamA=m.teamB=1;m.option=1;m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();var ice=SportsEventAuthoring.Mat(Folder,"Curling ice",new Color(.75f,.88f,.92f),.7f);var white=SportsEventAuthoring.Mat(Folder,"Ice ivory",new Color(.93f,.94f,.9f));var blue=SportsEventAuthoring.Mat(Folder,"Blue stones",new Color(.08f,.6f,.93f),.7f);var orange=SportsEventAuthoring.Mat(Folder,"Orange stones",new Color(1,.4f,.08f),.7f);var navy=SportsEventAuthoring.Mat(Folder,"Cab navy",new Color(.018f,.035f,.05f));var mint=SportsEventAuthoring.Mat(Folder,"Cab instruments",new Color(.22f,1,.75f));var contact=SportsEventAuthoring.Contact(Folder,"Frictionless stone ice",0,.04f);
  SportsEventAuthoring.Box("Extra slippery curling sheet",new Vector3(0,-.2f,CurlingRules.SheetCenter),new Vector3(16,.4f,CurlingRules.SheetLength),ice,contact);for(int sign=-1;sign<=1;sign+=2){SportsEventAuthoring.Box("Sideline",new Vector3(sign*CurlingRules.HalfWidth,.014f,CurlingRules.SheetCenter),new Vector3(.09f,.025f,CurlingRules.SheetLength-6),orange);SportsEventAuthoring.Box("Outer arena boards",new Vector3(sign*8.2f,.5f,CurlingRules.SheetCenter),new Vector3(.3f,1,CurlingRules.SheetLength),navy,BankMaterial());}SportsEventAuthoring.Box("Release stripe",new Vector3(0,.015f,0),new Vector3(14,.03f,.18f),mint);SportsEventAuthoring.Box("Far hog line",new Vector3(0,.016f,CurlingRules.Hog),new Vector3(14,.03f,.18f),orange);SportsEventAuthoring.Box("Tee line",new Vector3(0,.016f,CurlingRules.Tee),new Vector3(14,.03f,.07f),blue);SportsEventAuthoring.Box("Back line",new Vector3(0,.016f,CurlingRules.Back),new Vector3(14,.03f,.08f),orange);SportsEventAuthoring.Box("Center line",new Vector3(0,.017f,81),new Vector3(.06f,.02f,210),navy);
  Ring("Outer house",new Vector3(0,.026f,CurlingRules.Tee),CurlingRules.HouseRadius,blue,.13f);Ring("Middle house",new Vector3(0,.028f,CurlingRules.Tee),3.05f,white,.16f);Ring("Inner house",new Vector3(0,.03f,CurlingRules.Tee),1.53f,orange,.15f);Ring("Button",new Vector3(0,.032f,CurlingRules.Tee),.3f,blue,.2f);SportsEventAuthoring.Label("House title","TRUCK CURLING",new Vector3(0,3,189),.35f,Color.white);SportsEventAuthoring.Label("Release marker","RELEASE",new Vector3(-7.5f,.12f,0),.12f,Color.white).transform.rotation=Quaternion.Euler(90,0,0);
  m.stones=new CurlingStone[16];var mesh=StoneMesh();for(int i=0;i<16;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Curling truck-stone "+(i+1),new Vector3(0,.38f,CurlingRules.Start),i%8);UnityEngine.Object.DestroyImmediate(t.shape);t.shape=null;var shape=t.gameObject.AddComponent<MeshCollider>();shape.sharedMesh=mesh;shape.convex=true;shape.sharedMaterial=contact;t.body.constraints=RigidbodyConstraints.FreezeRotationX|RigidbodyConstraints.FreezeRotationZ;t.body.linearDamping=0;t.body.angularDamping=.35f;t.body.mass=12;t.body.maxLinearVelocity=20;var foot=new GameObject("Visible circular stone footprint",typeof(MeshFilter),typeof(MeshRenderer));foot.transform.SetParent(t.transform,false);foot.GetComponent<MeshFilter>().sharedMesh=mesh;foot.GetComponent<MeshRenderer>().sharedMaterial=i%2==0?blue:orange;var stone=t.gameObject.AddComponent<CurlingStone>();stone.match=m;stone.truck=t;stone.delivery=i;stone.footprint=foot.GetComponent<Renderer>();var guard=new GameObject("Protected free guard halo").AddComponent<LineRenderer>();guard.transform.SetParent(t.transform,false);guard.useWorldSpace=false;guard.positionCount=49;guard.startWidth=guard.endWidth=.08f;guard.sharedMaterial=mint;for(int k=0;k<49;k++){float a=k*Mathf.PI*2/48;guard.SetPosition(k,new Vector3(Mathf.Cos(a)*1.72f,-.27f,Mathf.Sin(a)*1.72f));}stone.protectedRing=guard;m.stones[i]=stone;t.gameObject.SetActive(false);}
  m.cabCamera=SportsEventAuthoring.Camera("Curling in-cab driver camera");m.cameras=new[]{m.cabCamera.view};m.cabCamera.view.nearClipPlane=.04f;m.cabCamera.Pose(new Vector3(0,1,15),new Vector3(0,0,-25),68,true);m.cab=new GameObject("Stable in-cab presentation");m.cab.transform.SetParent(m.cabCamera.transform,false);SportsEventAuthoring.Box("Dashboard",new Vector3(0,-.45f,.65f),new Vector3(1.9f,.5f,.45f),navy,null,m.cab.transform);SportsEventAuthoring.Box("Windshield top",new Vector3(0,.62f,.6f),new Vector3(1.9f,.07f,.08f),navy,null,m.cab.transform);for(int sign=-1;sign<=1;sign+=2)SportsEventAuthoring.Box("Windshield pillar",new Vector3(sign*.8f,.12f,.6f),new Vector3(.055f,1.05f,.065f),navy,null,m.cab.transform);for(int i=0;i<3;i++)SportsEventAuthoring.Box("Instrument panel",new Vector3(-.5f+i*.16f,-.25f,.43f),new Vector3(.11f,.04f,.015f),mint,null,m.cab.transform);SetLayer(m.cab.transform,23);m.cab.SetActive(false);
  m.houseCamera=new GameObject("Tactical house inset").AddComponent<Camera>();m.houseCamera.transform.position=new Vector3(0,26,CurlingRules.Tee);m.houseCamera.transform.rotation=Quaternion.Euler(90,0,0);m.houseCamera.orthographic=true;m.houseCamera.orthographicSize=8.5f;m.houseCamera.rect=new Rect(.73f,.61f,.25f,.29f);m.houseCamera.depth=10;m.houseCamera.clearFlags=CameraClearFlags.SolidColor;m.houseCamera.backgroundColor=new Color(.025f,.055f,.07f);m.houseCamera.cullingMask=~(1<<23);SportsEventAuthoring.UI(m);m.menus.teamAText.color=blue.color;m.menus.teamBText.color=orange.color;SportsEventAuthoring.Save(Folder);Validate();}
 static void SetLayer(Transform t,int layer){t.gameObject.layer=layer;foreach(Transform child in t)SetLayer(child,layer);}
 public static void Validate(){Fixtures();EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<CurlingMatch>();if(m==null||m.stones.Length!=16||m.houseCamera==null||m.cab==null||m.stones.Any(s=>s.truck.GetComponents<Collider>().Length!=1||s.GetComponent<MeshCollider>()==null)||UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Curling saved references/footprints invalid");Debug.Log("CURLING_SAVED_VALIDATED");}
 public static PhysicsMaterial BankMaterial(){var m=SportsEventAuthoring.Contact(Folder,"Legal bank rebound",0,.74f);m.bounceCombine=PhysicsMaterialCombine.Maximum;EditorUtility.SetDirty(m);return m;}
 public static void Fixtures(){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Curling fixture: "+label);count++;};check(CurlingRules.House(new Vector3(6.19f,0,CurlingRules.Tee)),"footprint biter qualifies");check(!CurlingRules.House(new Vector3(6.21f,0,CurlingRules.Tee)),"outside house rejected");check(!CurlingRules.SideOrBack(new Vector3(6.45f,0,50)),"legal side-wall bank stays in play");check(!CurlingRules.SideOrBack(new Vector3(0,0,CurlingRules.Back+.5f)),"part beyond back remains");check(CurlingRules.SideOrBack(new Vector3(0,0,CurlingRules.Back+1.7f)),"whole footprint beyond back removes");check(!CurlingRules.HogQualified(new Vector3(0,0,CurlingRules.Hog+1.5f),false)&&CurlingRules.HogQualified(new Vector3(0,0,CurlingRules.Hog+1.7f),false),"full hog crossing");check(CurlingRules.HogQualified(new Vector3(0,0,25),true),"contact exception qualifies");check(CurlingRules.Guard(new Vector3(4,0,CurlingRules.Hog+4.5f),false),"guard outside house before tee");for(int i=0;i<6;i++)check(CurlingRules.Protected(i,0,1,true)==(i<5),"five-rock protection boundary "+i);check(!CurlingRules.Protected(2,0,0,true),"own guards not protected");check(CurlingRules.HammerAfter(1,-1,0)==1&&CurlingRules.HammerAfter(1,1,2)==0,"blank retains/scorer gives hammer");var p=new[]{new Vector3(0,0,CurlingRules.Tee),new Vector3(2,0,CurlingRules.Tee),new Vector3(3,0,CurlingRules.Tee)};var t=new[]{0,0,1};var v=new[]{true,true,true};check(CurlingRules.Score(p,t,v,3,out int team)==2&&team==0,"closer-than-opposition scoring");p[2]=new Vector3(0,0,CurlingRules.Tee);check(CurlingRules.Score(p,t,v,3,out team)==0&&team==-1,"equal closest distance blank");for(int h=0;h<2;h++){int[] n={0,0};for(int i=0;i<16;i++)n[CurlingRules.TeamFor(i,h)]++;check(n[0]==8&&n[1]==8&&CurlingRules.TeamFor(15,h)==h,"eight each/hammer last "+h);}Debug.Log("CURLING_RULE_FIXTURES_PASS count="+count);}
}
}
